def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form, following symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: The current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    # Process path components
    while remaining:
        # Split off the next component
        if '/' in remaining:
            component, remaining = remaining.split('/', 1)
        else:
            component = remaining
            remaining = ''

        # Skip empty components and '.'
        if not component or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if this path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[current]

            # Resolve the target
            if target.startswith('/'):
                current = '/'
                target = target[1:]
            else:
                # Target is relative to the directory containing the link
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'

            # Prepend target components to remaining
            if target:
                remaining = target + ('/' + remaining if remaining else '')
            # else: remaining stays the same

    # Return the result, removing trailing slash unless it's '/'
    if current == '/':
        return '/'
    else:
        return current

